    guides: [
      cg({ slug: 'kuching-waterfront-old-courthouse', name: 'Kuching Waterfront & Old Courthouse', motif: 'river-city cabinet', instrument: 'zine', image: imageCredits.sarawakWaterfront,
        reviewedOn: '12 October 2026', reviewedOnIso: '2026-10-12',
        summary: 'Walk Kuching’s Old Courthouse, southern-bank Waterfront, Main Bazaar and Carpenter Street as one public city sequence, with a Padang Merdeka finish and a weather-aware return.',
        lead: 'The Sarawak River is Kuching’s orientation line, but the useful central walk is mostly a same-bank sequence. Read civic frontage, working shops and the promenade together; do not turn a scenic map line into an assumed signed trail or river-crossing service.',
        orientation: 'Start at the Old Courthouse, follow the open waterfront toward Pangkalan Batu and Square Tower, turn through Main Bazaar and Carpenter Street, then finish near Padang Merdeka. Add the museum only when its current hours leave enough time.',
        arrival: 'Use the Old Courthouse or Padang Merdeka as the pickup landmark, not an unnamed “waterfront” pin. If arriving from Kuching International Airport (KCH), confirm the hotel address and transfer before landing; downtown is compact but afternoon heat and rain can make the return walk less comfortable.',
        sequence: 'Old Courthouse → same-bank Waterfront → Pangkalan Batu/Square Tower → Main Bazaar → Carpenter Street → Padang Merdeka. Walk the sequence at your own pace and return to the named base on open streets or a confirmed ride.',
        boundary: 'This is a working commercial and worship district. Ask before photographing people or interiors, leave doorways clear, and do not enter port or private premises.',
        planningNotes: 'Stay near the Waterfront, Old Courthouse or Padang Merdeka if this is your first Kuching base. Give the walk a daylight block and place a meal or dusk stop near the hotel side. The Tourism Board describes a 1.5 km southern-bank promenade, but the full street sequence adds inland blocks; do not read that figure as the total route or a measured walking time. No cross-river boat is needed for this plan.',
        weatherFallback: 'In midday heat or a downpour, shorten the open riverfront section, move to a verified museum visit, or return by a confirmed taxi/e-hailing ride. If a festival closes part of the promenade, follow posted diversions rather than forcing the planned loop.',
        stages: [['Civic start', 'Begin at the Old Courthouse and check which public exhibits or event areas are open; exterior access does not guarantee interior entry.'], ['River edge', 'Use the public south-bank Kuching Waterfront toward Pangkalan Batu and Square Tower. Keep the river as a view and settlement line; no boat crossing is required.'], ['Trading streets', 'Turn through Main Bazaar and Carpenter Street. Choose one or two open businesses instead of treating the active street as a photo set.'], ['Finish and return', 'End by Padang Merdeka and the Borneo Cultures Museum. Check the museum’s current last admission separately, then walk back on open public streets or meet the prearranged driver.']],
        risks: [['Heat, rain and paving', 'Open promenade and street crossings are exposed; shorten the loop when surfaces are wet or the group is tiring.'], ['Access versus attraction', 'A landmark listing does not promise access to a building, event space or worship interior.'], ['Pickup ambiguity', 'Old Courthouse, Padang Merdeka and the river edge are different meeting points; send the driver one exact pin.']],
        duration: 'Reserve a half-day walking block; add a separate museum block if you want to explore several floors. Timing is a pacing suggestion, not a measured route duration.',
        combine: 'The museum is the natural same-neighborhood addition. Keep Semenggoh and Bako on separate days with confirmed return transport.',
        verify: 'Check Sarawak Tourism Board’s current city/event notices, the museum’s date-specific opening, METMalaysia’s Kuching forecast, public access and your exact return pickup.',
        sources: [['https://www.sarawaktourism.com/web/places-to-visit/town-view/kuching', 'Sarawak Tourism Board — Kuching Waterfront, Old Courthouse, Carpenter Street and city landmarks']],
        faq: [['Is this an official signed Kuching heritage trail?', 'No. It is a suggested public-street sequence using named landmarks. Confirm openings, event closures and public access on the day; do not assume every interior is open.'], ['Do I need a river boat for this walk?', 'No. The route stays on the south bank and returns through central streets. Add a river crossing only after identifying a currently operating public service, its landing and fare.'], ['Can I include the Borneo Cultures Museum?', 'Yes, because it is by Padang Merdeka, but plan it as a separate block and check the current last-admission time and holiday closure before walking there.']] }),
      cg({ slug: 'borneo-cultures-museum', name: 'Borneo Cultures Museum', motif: 'five-level reading plan', instrument: 'atlas', image: imageCredits.sarawakMuseum,
        reviewedOn: '12 October 2026', reviewedOnIso: '2026-10-12',
        summary: 'Read the Borneo Cultures Museum through its named river, nature, history and objects galleries, with dated ticket and last-entry checks beside Padang Merdeka.',
        lead: 'The five-storey Borneo Cultures Museum is next to Padang Merdeka. A good visit is a short curatorial question, not a race to photograph every floor: connect river, forest, community and historical change through the museum’s own labels.',
        orientation: 'The museum department currently names the second-floor children’s gallery “Love our Rivers”, the third-floor “In Harmony with Nature”, fourth-floor “Time Changes” and fifth-floor “Objects of Desire”. Choose two or three lenses and confirm the current map and access notices at entry.',
        arrival: 'The official address is Jalan Tun Abang Haji Openg beside Padang Merdeka. Walk from a central base or use a confirmed taxi/e-hailing drop at the museum entrance. The department lists car, taxi, bus and e-hailing from the city centre; it does not establish a stop or departure that fits every hotel.',
        sequence: 'Check the date and ticket first, orient at the current visitor map, choose one river/environment gallery, then one community or historical lens, and leave time for a seated pause before the exit.',
        boundary: 'Use the museum’s community names and interpretation. Follow photography restrictions, do not flatten living peoples into a generic “tribal” category, and treat ceremonies and sacred objects with care.',
        planningNotes: 'On the museum page last updated 7 October 2026, the listed hours are Monday–Friday 09:00–16:45 and weekends/public holidays 09:30–16:30, with last admission at 16:00. The same page lists named holiday closures; Service Sarawak also says the ticket is a one-time PDF redemption and that a SarawakID account is needed for online purchase. Recheck the exact date, current galleries, fees, ticket rules and any closure before building the walk around this stop.',
        weatherFallback: 'This is a useful indoor anchor during rain, but do not assume it is open on a listed closure or that a ticket grants entry after last admission. If galleries are closed or crowded, keep the visit selective and use a covered meal or hotel rest rather than rushing the rest of Kuching.',
        stages: [['Date and ticket', 'Read the museum and Service Sarawak notices for the exact day; last admission is earlier than closing, and the holiday list can change.'], ['Choose a question', 'Pick an environment, river, community or historical question before entering; use the current floor plan rather than an old screenshot.'], ['Read two lenses', 'Compare one named gallery with one other level, following curator language and photography rules.'], ['Synthesize', 'Pause, record a question and exit toward Padang Merdeka. Add the waterfront only if heat, rain and remaining daylight suit.']],
        risks: [['Last entry and closures', 'The official page lists a 16:00 last admission and specific holiday closures; verify the travel date.'], ['Five-floor fatigue', 'A complete building is not the same as a useful visit; choose a manageable reading plan.'], ['Ticket process', 'Online ticket terms and accepted payment can change; read the official ticket page before purchase.']],
        duration: 'Reserve three to five hours only if you want a long museum visit; a shorter, focused visit works when you choose galleries before arrival.',
        combine: 'The Old Courthouse and Waterfront are nearby street chapters. Do not combine the museum with a full Semenggoh or Bako transfer day.',
        verify: 'Check the Sarawak Museum Department date notice, Service Sarawak ticket page, last admission, current gallery map, photography rules and the exact return pickup.',
        sources: [['https://museum.sarawak.gov.my/web/subpage/webpage_view/169', 'Sarawak Museum Department — Borneo Cultures Museum'], ['https://service.sarawak.gov.my/web/web/home/sla_view/0/646/', 'Service Sarawak — museum ticket terms']],
        faq: [['What time does the museum stop admitting visitors?', 'The Sarawak Museum Department page checked for this review lists last admission at 16:00, before the stated closing time. Recheck your date, especially around public holidays.'], ['Do I need to see all five floors?', 'No. Use the current floor map and the gallery names to choose two or three questions. Leave breaks and read the specific community and curator interpretation.'], ['Can I buy a ticket online?', 'Service Sarawak lists an online PDF ticket process and says a SarawakID account is required. The ticket terms and fees can change, so verify before purchase.']] }),
      cg({ slug: 'semenggoh-wildlife-centre', name: 'Semenggoh Wildlife Centre', motif: 'rehabilitation-distance log', instrument: 'field', image: imageCredits.sarawakSemenggoh,
        reviewedOn: '12 October 2026', reviewedOnIso: '2026-10-12',
        summary: 'Plan Semenggoh’s 24 km city-to-reserve return around the official session, e-ticket process and wildlife distance without promising an orangutan sighting.',
        lead: 'Sarawak Forestry describes Semenggoh as a semi-wild reserve focused on orangutan biology and behaviour; earlier rehabilitation work has reached the forest’s capacity. Visitors are guests in a living habitat, and no appearance or close view is owed.',
        orientation: 'Choose the visitor window published by Sarawak Forestry for your date, leave a road margin from Kuching, and treat the conservation interpretation as the visit’s core even when orangutans stay out of view.',
        arrival: 'The official SFC page places Semenggoh Nature Reserve 24 km from Kuching. Book a named return taxi/driver or an operator transfer to the reserve entrance; confirm both pickup times and the precise gate. A one-way e-hailing result does not guarantee a car for the return.',
        sequence: 'Confirm current session and entry → travel to the gate → complete registration and staff briefing → observe only from authorized areas → meet the named return ride.',
        boundary: 'Never feed, call, touch, crowd, use flash where prohibited or cross a barrier for a photograph. Follow staff distance, hygiene and path instructions; visitors do not control wildlife movement.',
        planningNotes: 'Protect a half-day window including both road legs. Sarawak Forestry links Visitor Self Registration, E-Booking and E-Ticketing; Service Sarawak says a SarawakID account is required before park-ticket purchase and pre-registration is needed before entry. The exact visitor sessions, capacity, admission and transport timings were not independently confirmed in this review, so use the live official portal and reserve the road return before leaving the city.',
        weatherFallback: 'If rain, a session change or a delayed driver breaks the plan, follow staff instructions and ask the operator for a newly confirmed return. Do not stay after the agreed pickup hoping for a replacement car. If no official visitor window fits, move the day to Kuching’s museum and streets; do not visit a different forest edge to chase an animal.',
        stages: [['Book the window', 'Check the current SFC visitor notice, e-ticket and self-registration flow for the actual date. No fixed session time is promised on this page.'], ['Road out', 'Use the confirmed car or operator and save the pickup contact, entrance pin and return time.'], ['Observe responsibly', 'Attend the briefing, keep a quiet distance and accept a non-sighting as a normal outcome.'], ['Return to base', 'Meet the driver at the agreed gate and keep the evening free of a flight, Bako boat or another fixed tour.']],
        risks: [['Wildlife uncertainty', 'Semi-wild orangutans may not appear during a visitor window.'], ['Session and entry', 'Capacity, visitor hours and e-ticket procedure require a current official check.'], ['Return transport', 'The reserve is outside the city; arrange the second road leg before departure.']],
        duration: 'Keep at least a half day for the official visit plus the Kuching road return; do not schedule against an unverified session length.',
        combine: 'Pair with a light city meal only if the confirmed return leaves room. Bako is a separate boat-linked day.',
        verify: 'Check Sarawak Forestry’s current Semenggoh and self-registration pages, Service Sarawak ticket eligibility, the day’s weather and both named road pickups.',
        sources: [['https://sfc.sarawak.gov.my/web/subpage/webpage_view/58', 'Sarawak Forestry Corporation — Semenggoh Wildlife Centre'], ['https://service.sarawak.gov.my/web/web/home/sla_view/0/690/', 'Service Sarawak — park and wildlife-centre tickets']],
        faq: [['Will I see an orangutan?', 'There is no guarantee. The centre describes semi-wild animals living in a natural habitat; quiet observation and conservation learning remain the purpose if none appears.'], ['How far is Semenggoh from Kuching?', 'Sarawak Forestry lists the reserve as 24 km from Kuching. That is a location description, not a live journey time; confirm the entrance, traffic margin and return car.'], ['Can I take a public bus?', 'This review did not confirm a current public route to the reserve gate. Use an operator or a prearranged return driver unless the live official route and last return are verified for your date.']] }),
      cg({ slug: 'bako-national-park', name: 'Bako National Park', motif: 'tide-and-trail contract', instrument: 'tide', image: imageCredits.sarawakBako,
        reviewedOn: '12 October 2026', reviewedOnIso: '2026-10-12',
        summary: 'Build Bako as a full city-to-terminal-to-boat park day, checking BAS.MY’s named route, registration, tide, one open trail and the return chain.',
        lead: 'Bako is not just a scenic drive: the Kuching-to-park chain has road, boat, registration and trail links. A day works only when the exact terminal, boat counter, park entry, tide, daylight and return are all confirmed together.',
        orientation: 'Sarawak Tourism Board describes travel from Kuching to Bako Village followed by a boat to the park. Biaramas’ BAS.MY page separately lists a “Bako” route between Stesen Bas Saujana and Terminal Bako. Match the current route map and departure PDF to the boat check-in point before relying on the bus.',
        arrival: 'Choose the transport chain first: date-checked BAS.MY “Bako” bus plus a confirmed connection to the park boat, or a prearranged return car to Bako Village. Then follow Sarawak Forestry’s current e-ticket/self-registration and boat instructions. Do not assume Terminal Bako is the same as the boat counter without confirming the last handoff.',
        sequence: 'Kuching base → confirmed road leg and terminal → named boat check-in → park registration and briefing → one open trail matched to tide, ability and daylight → assigned boat and booked return to the same base.',
        boundary: 'Keep distance from proboscis monkeys, macaques and other wildlife; secure food and bags. Stay on open trails, obey rangers and never attempt a beach landing or swim outside current permission.',
        planningNotes: 'Give Bako a full day from the central Kuching base and keep the evening flexible. Sarawak Tourism Board’s page gives a broad 30-minute road and 20-minute boat orientation, but these are not a current timetable or connection guarantee; BAS.MY publishes exact-date PDFs for Terminal Bako ↔ Stesen Bas Saujana, and the park boat must be checked separately. For an overnight, confirm current park accommodation, meals, check-in and return boat directly before changing bases. No bus fare, boat fare or departure time is asserted here.',
        weatherFallback: 'Sarawak Tourism Board describes March–October as relatively drier and November–February as wetter, but daily rain, tide, sea state and trail notices decide whether to go. If the operator or ranger delays, limits or cancels access, do not force the landing or trail; use the central-base museum/city reserve day and reconfirm a new chain before paying for another trip.',
        stages: [['Check the links', 'Read the current BAS.MY Bako route PDF and map, verify the Terminal Bako-to-boat connection, and confirm a road alternative and return.'], ['Register and board', 'Complete the current Sarawak Forestry ticket and pre-registration steps; use the assigned boat, life-jacket briefing and park instructions.'], ['Choose one trail', 'Ask staff which trail is open, then match its length and footing to tide, weather, daylight and the group.'], ['Return early', 'Meet the assigned boat with margin, then use the confirmed bus or waiting driver. Do not attach Semenggoh or a fixed evening flight.']],
        risks: [['Bus-to-boat handoff', 'The BAS.MY terminal name alone does not identify your boat counter or prove a connection.'], ['Tide and sea state', 'Landing, beach routes and boats can change with conditions.'], ['Trail and daylight', 'Closures, wet footing and return timing may reduce the route choice.']],
        duration: 'Reserve a full day including the city-to-terminal road leg, boat, registration, trail and return buffer.',
        combine: 'Do not combine with Semenggoh, an unconfirmed same-day river crossing or a fixed evening flight.',
        verify: 'Check Sarawak Forestry park entry/self-registration, the Bako trail notice, BAS.MY’s current Bako route map/PDF, boat and terminal handoff, tide, sea/weather and return pickup.',
        sources: [['https://www.sarawaktourism.com/web/things-to-do/thing-view/nature/national-parks-wildlife-reserves/bako-national-park', 'Sarawak Tourism Board — Bako access, trails and seasonal context'], ['https://busasia.my/biaramas-consumer/consumer/bas-timetable/', 'Biaramas / BAS.MY — current Bako route and timetable'], ['https://service.sarawak.gov.my/web/web/home/sla_view/0/690/', 'Service Sarawak — park e-ticket and pre-registration']],
        faq: [['Does the BAS.MY Bako route take me straight to the park boat?', 'Do not assume so. The operator lists Stesen Bas Saujana and Terminal Bako; the Tourism Board describes Bako Village and a boat leg. Match the current bus map, stop, boat counter and return before booking.'], ['How long does the Bako transfer take?', 'Sarawak Tourism Board’s page gives a broad road-and-boat orientation, but it is not a current timetable or guaranteed connection. Check the bus PDF, boat operator and weather for your date.'], ['Can I choose a trail in advance?', 'Choose a preferred route only after asking park staff which trails are open. Tide, rain, sea state, footing and daylight can change the safe choice.'], ['Which months are best?', 'The Tourism Board characterizes March–October as relatively drier and November–February as heavier rain. Treat that as a broad pattern; check the live district forecast, tide and park/boat notices.']] })
    ]
